{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Rates &amp; Offerings — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Clear, practical options for brief work or deeper focus. Sessions and intensives tailored to life shifts.">
  <style>
    :root{--bg:#f6efe7;--accent:#6a4a3c;--muted:#8a7f74;--card:#fff6f1;--glass:rgba(255,255,255,0.6);--accent2:#c48a6f}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:var(--accent);background:linear-gradient(180deg,var(--bg),#efe6dc);}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:transparent}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:48px;height:48px;border-radius:10px;background:linear-gradient(135deg,var(--accent2),var(--accent));display:grid;place-items:center;color:#fff;font-weight:700}
    nav a{margin:0 8px;color:var(--accent);text-decoration:none;font-weight:600}
    .container{max-width:960px;margin:24px auto;padding:20px}
    .hero{padding:28px;border-radius:14px;background:linear-gradient(180deg,var(--card),#fff);box-shadow:0 6px 24px rgba(106,74,60,0.06);display:grid;gap:10px}
    h1{margin:0;font-size:clamp(20px,3.8vw,30px)}
    p.lead{margin:0;color:var(--muted)}
    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px;margin-top:20px}
    .plan{background:var(--glass);backdrop-filter:blur(6px);padding:16px;border-radius:12px;border:1px solid rgba(106,74,60,0.06)}
    .plan h3{margin:0 0 8px 0}
    .price{font-size:20px;color:var(--accent2);font-weight:700}
    .benefits{font-size:14px;color:var(--muted);margin:8px 0}
    .cta{display:inline-block;margin-top:10px;padding:10px 14px;border-radius:8px;background:var(--accent);color:#fff;text-decoration:none}
    footer{margin-top:28px;padding:18px 14px;border-radius:10px;background:#fff6f1;color:var(--muted);font-size:13px}
    .small{font-size:13px;color:var(--muted)}
    /* reveal */
    .reveal{opacity:0;transform:translateY(14px);transition:opacity .6s ease,transform .6s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
    /* subtle pattern */
    .pattern{position:fixed;right:-150px;top:-120px;width:420px;height:420px;opacity:0.08;background:url("assets/img/pattern.svg") no-repeat center/cover;pointer-events:none}
  </style>
</head>
<body>
  <div class="pattern" aria-hidden="true"></div>
  <header>
    <div class="brand">
      <div class="logo">TP</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav aria-label="Primary">
      <a href="index.html">Nest</a>
      <a href="about.html">Philosophy</a>
      <a href="specialties.html">Focus Areas</a>
      <a href="fees.html" style="text-decoration:underline">Rates</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="container">
    <section class="hero reveal" id="intro">
      <h1>Choices that match the pace you need</h1>
      <p class="lead">Short sessions for check-ins, focused intensives for a deeper look, and flexible pathways when you want to keep going. Pricing is clear and centered on what you want to work on.</p>
    </section>

    <section class="grid" id="plans">
      <article class="plan reveal">
        <h3>Single Session — Exploratory</h3>
        <div class="price">$160 / 55 min</div>
        <div class="benefits">A focused hour to name priorities, try a new approach, or make a plan. Useful when you need an outside perspective.</div>
        <a class="cta" href="book.html">Book one session</a>
      </article>

      <article class="plan reveal">
        <h3>Short Course — Three-Session Work</h3>
        <div class="price">Package $430 (3 × 50 min)</div>
        <div class="benefits">A deliberate, short arc for a defined concern: transitions, decision-making, or skill practice with accountability between sessions.</div>
        <a class="cta" href="book.html">Plan a short course</a>
      </article>

      <article class="plan reveal">
        <h3>Focused Intensive — Half-Day</h3>
        <div class="price">$720 / 3 hours</div>
        <div class="benefits">A concentrated session to clarify complex choices, set an action roadmap, or work through an urgent relational knot. Includes pre-session intake and written summary.</div>
        <a class="cta" href="book.html">Enquire about an intensive</a>
      </article>

      <article class="plan reveal">
        <h3>Ongoing Support — Block Sessions</h3>
        <div class="price">Custom block pricing</div>
        <div class="benefits">If you prefer continuity, we structure periodic blocks that fit into your life—short-term commitments with an eye toward rhythm rather than open-ended obligation.</div>
        <a class="cta" href="contact.html">Discuss options</a>
      </article>
    </section>

    <section class="hero reveal" style="margin-top:20px">
      <h2>Notes on practice &amp; scope</h2>
      <p class="small">I provide psychotherapy grounded in evidence-informed practice. I do not offer medical diagnoses or emergency services. I keep confidentiality as described in our intake paperwork, with legally required exceptions for safety concerns. If you are in crisis or immediate danger, please call your local emergency number or contact crisis services in {{CITY}}, {{STATE}}.</p>
    </section>

    <footer class="reveal">
      <strong>Contact</strong>
      <div class="small">Phone: {{PHONE}} • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      <div style="margin-top:8px" class="small">Appointments happen with mutual consent; payment policies, cancellation windows, and confidentiality terms are shared at intake. I aim to create a contained, respectful space — responsibilities, boundaries, and limits of confidentiality will be discussed before work begins.</div>
    </footer>
  </main>

  <script>
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      function revealAll(){document.querySelectorAll('.reveal').forEach(el=>el.classList.add('visible'))}
      if(prefersReduced){revealAll();return}
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target)}});
      },{threshold:0.12});
      document.querySelectorAll('.reveal').forEach(el=>obs.observe(el));
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Questions & Answers — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Common questions about sessions, privacy, and how we work together.">
  <style>
    :root{--bg:#f7efe6;--accent:#5a433a;--muted:#7d6f67;--card:#fffaf6;--accent2:#c28a6c}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:linear-gradient(180deg,var(--bg),#efe5dc);color:var(--accent)}
    header{padding:18px 24px;display:flex;justify-content:space-between;align-items:center}
    .logo{width:44px;height:44px;background:linear-gradient(135deg,var(--accent2),var(--accent));border-radius:8px;color:#fff;display:grid;place-items:center;font-weight:700}
    main{max-width:900px;margin:12px auto;padding:20px}
    h1{margin:0 0 8px 0}
    .faq{margin-top:18px}
    .q{background:linear-gradient(180deg,var(--card),#fff);padding:14px;border-radius:10px;margin-bottom:12px;border:1px solid rgba(90,67,58,0.06)}
    .q h3{margin:0;font-size:16px}
    .a{margin-top:8px;color:var(--muted);font-size:15px}
    .reveal{opacity:0;transform:translateY(10px);transition:opacity .5s ease,transform .5s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
    footer{margin-top:18px;padding:12px;background:#fff6f2;border-radius:10px;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">TP</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html" style="margin-right:8px;color:var(--accent)">Home</a>
      <a href="approach.html" style="margin-right:8px;color:var(--accent)">Approach</a>
      <a href="fees.html" style="margin-right:8px;color:var(--accent)">Rates</a>
      <a href="book.html" style="color:var(--accent)">Reserve</a>
    </nav>
  </header>

  <main>
    <h1>Frequently Asked Questions</h1>
    <p style="color:var(--muted);margin-top:6px">Practical answers for how we work together and what to expect.</p>

    <section class="faq">
      <div class="q reveal">
        <h3>What happens in a first session?</h3>
        <div class="a">We create a brief map: concerns that brought you here, what you hope to change, and some immediate steps you might try. We also cover confidentiality, logistics, and whether a short series or an intensive makes sense.</div>
      </div>

      <div class="q reveal">
        <h3>How long are sessions and how do payments work?</h3>
        <div class="a">Standard sessions are 50–55 minutes unless otherwise arranged. Payment is collected at booking or at the time of service depending on the option chosen. For packaged work or intensives, full details are provided before scheduling.</div>
      </div>

      <div class="q reveal">
        <h3>Do you accept insurance?</h3>
        <div class="a">I operate on a private-pay basis. I can provide a simple receipt (superbill) if you wish to submit for out-of-network reimbursement. Coverage and reimbursement depend on your plan.</div>
      </div>

      <div class="q reveal">
        <h3>Can I schedule an intensive instead of weekly sessions?</h3>
        <div class="a">Yes — intensive formats are offered for focused work when you want a concentrated timeframe. They include intake and a summary with suggested next steps. We discuss suitability before booking.</div>
      </div>

      <div class="q reveal">
        <h3>What if I'm in crisis?</h3>
        <div class="a">I am not an emergency service. If you are in immediate danger or need urgent help, please call your local emergency number. You may also contact crisis resources in {{CITY}}, {{STATE}} for immediate assistance.</div>
      </div>

      <div class="q reveal">
        <h3>How is confidentiality handled?</h3>
        <div class="a">Confidentiality is foundational. Exceptions are limited to legal requirements such as imminent harm to self or others, or court orders. These limits are reviewed during intake so there are no surprises.</div>
      </div>
    </section>

    <footer class="reveal">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <div>
          <div style="font-weight:700">Ready to talk?</div>
          <div style="color:var(--muted);">Call {{PHONE}} or <a href="mailto:{{EMAIL}}">email {{EMAIL}}</a></div>
        </div>
        <div>
          <a href="book.html" style="background:linear-gradient(90deg,var(--accent2),var(--accent));padding:10px 14px;color:#fff;border-radius:8px;text-decoration:none">Set a time</a>
        </div>
      </div>
    </footer>
  </main>

  <script>
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      function revealAll(){document.querySelectorAll('.reveal').forEach(el=>el.classList.add('visible'))}
      if(prefersReduced){revealAll();return}
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target)}});
      },{threshold:0.08});
      document.querySelectorAll('.reveal').forEach(el=>obs.observe(el));
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve &amp; Plan — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Begin by creating a short session plan, then reserve a time that fits your needs.">
  <style>
    :root{--bg:#f7efe6;--accent:#5b4136;--muted:#7b6d66;--card:#fffdf9;--accent2:#c28a6c}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:linear-gradient(180deg,#faf4ec,var(--bg));color:var(--accent)}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 20px}
    .logo{width:46px;height:46px;background:linear-gradient(135deg,var(--accent2),var(--accent));border-radius:10px;color:#fff;display:grid;place-items:center;font-weight:700}
    main{max-width:980px;margin:18px auto;padding:18px}
    .two{display:grid;grid-template-columns:1fr 360px;gap:18px}
    .panel{background:var(--card);padding:16px;border-radius:12px;border:1px solid rgba(91,65,54,0.06)}
    h1{margin-top:0}
    label{display:block;margin-top:10px;font-weight:600}
    input[type=text],textarea,select{width:100%;padding:8px;margin-top:6px;border-radius:8px;border:1px solid rgba(91,65,54,0.12)}
    textarea{min-height:90px}
    .small{font-size:13px;color:var(--muted)}
    .btn{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none;border:none;cursor:pointer}
    .summary{white-space:pre-wrap;background:#fff;padding:12px;border-radius:10px;border:1px dashed rgba(91,65,54,0.08);min-height:120px}
    .reveal{opacity:0;transform:translateY(12px);transition:opacity .55s ease,transform .55s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
    .note{font-size:13px;color:var(--muted);margin-top:10px}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">TP</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html" style="margin-right:10px;color:var(--accent)">Home</a>
      <a href="specialties.html" style="margin-right:10px;color:var(--accent)">Focus</a>
      <a href="fees.html" style="margin-right:10px;color:var(--accent)">Rates</a>
      <a href="contact.html" style="color:var(--accent)">Contact</a>
    </nav>
  </header>

  <main>
    <div class="two">
      <section class="panel reveal" id="planner">
        <h1>Session Planner</h1>
        <p class="small">Build a compact plan that frames what you want to work on. Use it to guide a single session, a short course, or an intensive.</p>

        <form id="planForm" onsubmit="return false;">
          <label for="focus">Primary focus (one line)</label>
          <input id="focus" name="focus" type="text" placeholder="e.g., navigating a career shift" required>

          <label for="goal">What outcome feels meaningful to you?</label>
          <input id="goal" name="goal" type="text" placeholder="e.g., clarity about next steps" required>

          <label for="format">Preferred format</label>
          <select id="format" name="format">
            <option>Single exploratory session (55 min)</option>
            <option>Short series — 3 sessions</option>
            <option>Focused intensive (half-day)</option>
            <option>Unsure — want your recommendation</option>
          </select>

          <label for="length">If you chose a series or intensive, what pace fits you?</label>
          <select id="length" name="length">
            <option>Weekly</option>
            <option>Biweekly</option>
            <option>Block scheduling (monthly)</option>
          </select>

          <label for="barriers">Current barriers or considerations (brief)</label>
          <textarea id="barriers" name="barriers" placeholder="e.g., childcare, energy, access concerns"></textarea>

          <label for="notes">Anything else to share before booking</label>
          <textarea id="notes" name="notes" placeholder="Optional details, triggers, or preferences"></textarea>

          <button class="btn" id="buildBtn">Build plan</button>
        </form>

        <div class="note">The planner helps guide our work together. It is not a clinical record until you schedule and consent to intake paperwork.</div>
      </section>

      <aside class="panel reveal" id="preview">
        <h2>Plan preview</h2>
        <div id="summary" class="summary">Use the form to create a short, shareable plan. Click "Copy plan" to copy the plaintext summary to your clipboard.</div>
        <div style="margin-top:12px;display:flex;gap:8px">
          <button class="btn" id="copyBtn">Copy plan</button>
          <a class="btn" id="bookNow" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>
        <div id="copyMsg" class="small" style="margin-top:8px;color:var(--muted)"></div>

        <div style="margin-top:14px" class="small">If you prefer, you can call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> to discuss scheduling or accommodations.</div>
      </aside>
    </div>

    <section class="panel reveal" style="margin-top:18px">
      <h3>Before we meet</h3>
      <p class="small">I'll ask you a few intake questions ahead of a first appointment so we can use our time well. I keep conversations confidential, with the exceptions required by law for safety. I do not provide emergency services; if you are in danger or require immediate help, contact emergency services in {{CITY}}, {{STATE}}.</p>
    </section>
  </main>

  <script>
    // Reveal behavior
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      function revealAll(){document.querySelectorAll('.reveal').forEach(el=>el.classList.add('visible'))}
      if(prefersReduced){revealAll();return}
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target)}});
      },{threshold:0.08});
      document.querySelectorAll('.reveal').forEach(el=>obs.observe(el));
    })();

    // Session Planner logic
    (function(){
      const form = document.getElementById('planForm');
      const buildBtn = document.getElementById('buildBtn');
      const summaryEl = document.getElementById('summary');
      const copyBtn = document.getElementById('copyBtn');
      const copyMsg = document.getElementById('copyMsg');

      function trim(s){return s?String(s).trim():''}

      function makePlan(data){
        // Compose a plaintext plan that feels clinician-informed and grounded
        const lines = [];
        lines.push('Session Plan')
        lines.push('-------------')
        lines.push('Primary focus: ' + data.focus)
        lines.push('Meaningful outcome: ' + data.goal)
        lines.push('Preferred format: ' + data.format)
        if(data.format.toLowerCase().includes('series')||data.format.toLowerCase().includes('intensive')){
          lines.push('Pacing preference: ' + data.length)
        }
        if(data.barriers) lines.push('\nBarriers / access notes: ' + data.barriers)
        if(data.notes) lines.push('\nAdditional notes: ' + data.notes)
        lines.push('\nSuggested pre-session steps:')
        lines.push('- A short list of 2–3 concrete questions you want to explore')
        lines.push('- Anything you wish me to be mindful of (pronouns, triggers, energy patterns)')
        lines.push('\nNext steps: Bring this plan to the session; we will refine goals and set a practical first step together.')
        lines.push('\nContact: ' + '{{PHONE}}' + ' • ' + '{{EMAIL}}')
        return lines.join('\n')
      }

      function showPlan(text){summaryEl.textContent = text}

      buildBtn.addEventListener('click', function(){
        const data = {
          focus: trim(document.getElementById('focus').value),
          goal: trim(document.getElementById('goal').value),
          format: trim(document.getElementById('format').value),
          length: trim(document.getElementById('length').value),
          barriers: trim(document.getElementById('barriers').value),
          notes: trim(document.getElementById('notes').value)
        };
        if(!data.focus || !data.goal){
          summaryEl.textContent = 'Please add a primary focus and what outcome would feel meaningful.';return;
        }
        const text = makePlan(data);
        showPlan(text);
        copyMsg.textContent = '';
      });

      copyBtn.addEventListener('click', async function(){
        const text = summaryEl.textContent;
        if(!text) return;
        try{
          await navigator.clipboard.writeText(text);
          copyMsg.textContent = 'Plan copied to clipboard.';
        }catch(e){
          // fallback
          const ta = document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();
          try{document.execCommand('copy');copyMsg.textContent = 'Plan copied to clipboard.'}catch(e2){copyMsg.textContent = 'Could not copy — please select and copy manually.'}
          ta.remove();
        }
        setTimeout(()=>copyMsg.textContent='',4000);
      });

      // Preload a gentle example
      document.addEventListener('DOMContentLoaded',function(){
        const sample = {
          focus:'Navigating a career transition',
          goal:'Make a clear first 90-day plan',
          format:'Short series — 3 sessions',
          length:'Weekly',
          barriers:'Work schedule limits evenings; prefers remote sessions',
          notes:''
        };
        const text = makePlan(sample);
        showPlan(text);
      });
    })();
  </script>
</body>
</html>"} 
